CREATE TABLE IF NOT EXISTS websites(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,normalized_origin TEXT NOT NULL,username TEXT NOT NULL,password_credential_ref TEXT NOT NULL,capture_source TEXT NOT NULL CHECK(capture_source IN('manual','browser_extension')),notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(normalized_origin,username));
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,platform TEXT NOT NULL CHECK(platform IN('macos','windows')),display_name TEXT NOT NULL,platform_application_id TEXT NOT NULL,launch_target TEXT NOT NULL,path_access_ref TEXT,version TEXT,signature_identity TEXT NOT NULL,discovery_source TEXT NOT NULL CHECK(discovery_source IN('automatic','manual_import')),is_present INTEGER NOT NULL CHECK(is_present IN(0,1)),is_hidden INTEGER NOT NULL CHECK(is_hidden IN(0,1)),icon_cache_ref TEXT,last_discovered_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(platform,platform_application_id,launch_target));
CREATE TABLE IF NOT EXISTS application_accounts(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),display_name TEXT NOT NULL,username TEXT NOT NULL,password_credential_ref TEXT NOT NULL,auto_submit_enabled INTEGER NOT NULL CHECK(auto_submit_enabled IN(0,1)),last_login_status TEXT,last_login_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_templates(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),window_signature TEXT NOT NULL,window_size_class TEXT NOT NULL,username_rect TEXT NOT NULL,password_rect TEXT NOT NULL,submit_rect TEXT NOT NULL,provider_id TEXT NOT NULL,model_name TEXT NOT NULL,confidence_summary TEXT NOT NULL,user_confirmed_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
